System.register("chunks:///_virtual/manifest2.ts",["cc"],(function(e){var a;return{setters:[function(e){a=e.cclegacy}],execute:function(){a._RF.push({},"b6642d6mK1OYJndRi9/y9UN","manifest",void 0);e("MANIFEST",{manifest_version:1,game_id:"sg-snake",slug:"snake",name:{en:"Snake",it:"Snake"},description:{en:"Swipe to steer, eat to grow, never bite your own tail. The classic snake game, faster with every bite.",it:"Scorri per sterzare, mangia per crescere, non morderti la coda. Il classico gioco del serpente, più veloce a ogni boccone."},genre:"arcade",template_id:"snake",engine:"cocos-3.8.8",version:"1.0.0",orientation:"portrait",game_rules:{variant:"classic_snake",cols:15,rows:21,start_length:3,step_ms:130,min_step_ms:62,speedup_ms_per_food:2,golden_every:5,golden_steps:40,modes:[{id:"classic",walls:"solid"},{id:"portal",walls:"wrap"}]},scoring_rules:{food_points:10,golden_points:50},supported_platforms:["web","telegram"],supported_locales:["en","it"],default_locale:"en",target_countries:["*"],age_rating:"PEGI 3",privacy_profile:{personal_data:!1,analytics:"pseudonymous_install",account_required:!1},monetization_profile:{rewarded_ads:!1,interstitial_ads:!1,iap:!0},social_profile:{share:!0,leaderboard:!0,challenge:!0},analytics_profile:{sink:"memory",flush_interval_ms:5e3},difficulty_config:{level:"normal"},asset_manifest:{theme:"settegames",palette:{background:"#8CE04A",primary:"#FF2D8B",accent:"#FFC83D",text:"#1A0B4B",muted:"#F4F6FF"},sounds:"synth",provenance:"Rosa, giallo, inchiostro e bianco-lavanda dal brand kit SetteGames (Scopa/grafica/logo-settegames/marchio.json); campo verde lime scelto per questo gioco; caratteri Titan One e Baloo 2 (OFL, da Scopa); suoni sintetizzati dal codice; serpente, cibo e griglia disegnati dal codice. Direzione: .impeccable.md"},build_config:{targets:["web-mobile"],max_gzip_kb:1200},release_config:{channels:["web","telegram"],status:"draft"},legal_status:{original_concept:!1,trademark_check:"pending",gambling_mechanics:!1,notes:'"Snake" è il nome generico di un genere arcade di pubblico dominio (anni \'70). Nessun nome, marchio, grafica o suono di terzi: niente riferimenti a Nokia, Google o altre versioni note; serpente, cibo e interfaccia disegnati da codice in stile SetteGames.'},experiment_config:{active:[]},seo:{keywords:["snake game","play snake online","snake game online free","classic snake game","snake game no download","snake game for mobile","arcade snake","gioco del serpente"],headline:{en:"Play Snake online",it:"Gioca a Snake online"},long_description:{en:"Snake is the classic arcade game: steer a hungry snake around the grid, eat food to grow longer and try not to crash into the walls or your own tail. Every bite makes the snake a little faster. Play the Classic mode with solid walls or the Portal mode, where the edges wrap around. Free in your browser and on Telegram, no download and no sign-up.",it:"Snake è il classico gioco arcade: guida un serpente affamato sulla griglia, mangia per allungarti e non sbattere contro i muri o contro la tua coda. Ogni boccone lo rende un po' più veloce. Gioca in modalità Classica, con i muri, o Portale, dove i bordi fanno il giro. Gratis nel browser e su Telegram, senza download e senza registrazione."},how_to_play:{en:["Swipe anywhere on the screen to turn the snake (on a computer use the arrow keys or WASD).","Eat the white food to grow: every bite is worth 10 points.","Every fifth bite a golden treat appears for a short time: grab it for 50 points before it fades.","In Classic mode the walls are deadly; in Portal mode you come out on the opposite side.","The game ends when the snake hits a wall or bites its own body. Then beat your best or challenge a friend."],it:["Scorri in un punto qualsiasi dello schermo per far girare il serpente (al computer usa le frecce o WASD).","Mangia il cibo bianco per crescere: ogni boccone vale 10 punti.","Ogni cinque bocconi compare per poco un premio d'oro: prendilo prima che sparisca, vale 50 punti.","In modalità Classica i muri sono letali; in modalità Portale esci dal lato opposto.","La partita finisce quando il serpente sbatte contro un muro o si morde. Poi batti il tuo record o sfida un amico."]},faq:[{q:{en:"Is this snake game free?",it:"Questo gioco del serpente è gratis?"},a:{en:"Yes. You can play every mode for free in your browser or on Telegram. The only optional purchase is a pack of color themes, which is purely cosmetic and never changes your score.",it:"Sì. Tutte le modalità sono gratis nel browser o su Telegram. L'unico acquisto facoltativo è un pacchetto di temi colore, solo estetico, che non cambia mai il punteggio."}},{q:{en:"Do I need to download anything?",it:"Devo scaricare qualcosa?"},a:{en:"No. The game runs in any modern browser on phones, tablets and computers. No app and no account are needed.",it:"No. Il gioco funziona in qualsiasi browser recente su telefono, tablet e computer. Non servono app né account."}},{q:{en:"How do I control the snake?",it:"Come si controlla il serpente?"},a:{en:"Swipe in the direction you want to go. You can swipe twice quickly to queue two turns. On a keyboard, use the arrow keys or W, A, S, D. The snake can never turn straight back on itself.",it:"Scorri nella direzione in cui vuoi andare. Puoi scorrere due volte di fila per preparare due svolte. Con la tastiera usa le frecce oppure W, A, S, D. Il serpente non può mai tornare indietro su se stesso."}},{q:{en:"What is the difference between Classic and Portal?",it:"Che differenza c'è fra Classica e Portale?"},a:{en:"In Classic the edges of the grid are walls and touching them ends the game. In Portal the edges wrap around, so you can only lose by biting your own tail.",it:"In Classica i bordi della griglia sono muri e toccarli chiude la partita. In Portale i bordi fanno il giro, quindi si perde solo mordendosi la coda."}},{q:{en:"Any tips for a higher score?",it:"Qualche consiglio per fare più punti?"},a:{en:"Stay close to the walls and move in wide loops so your tail leaves open space behind you. Plan your next turn early, because the snake speeds up with every bite. Go for the golden treat only when the path is safe.",it:"Resta vicino ai bordi e muoviti a larghe curve, così la coda ti lascia spazio libero. Prepara la svolta in anticipo, perché il serpente accelera a ogni boccone. Punta al premio d'oro solo se la strada è sicura."}},{q:{en:"Is there a leaderboard?",it:"C'è una classifica?"},a:{en:"Yes. Every game is checked on our server and the best scores of the week appear on the result screen. You can also send a challenge link to a friend.",it:"Sì. Ogni partita viene verificata sul nostro server e i migliori punteggi della settimana compaiono nella schermata finale. Puoi anche mandare una sfida a un amico."}}]}}),e("BUILD_INFO",{hash:"02ab16562046b763",hubUrl:"https://jvmpwhoosojharlbmgsi.supabase.co/functions/v1/hub-api"});a._RF.pop()}}}));

